    const kairn::emulated::Number xl_h_s_h = xl_h_s_m ? rx : cx;
    const kairn::emulated::Number xl_h_s_l = xl_h_s_m ? cx : rx;
    // (xl_h_s, xl_h_e) = fast_two_sum(xl_h_s_h, xl_h_s_l)
    const kairn::emulated::Number xl_h_s = xl_h_s_h + xl_h_s_l;
    const kairn::emulated::Number xl_h_s_z = xl_h_s - xl_h_s_h;
    const kairn::emulated::Number xl_h_e = xl_h_s_l - xl_h_s_z;
    const bool xl_h_n = xl_h_e > kairn::emulated::constant(0);
    const kairn::emulated::Number xl_h_q = next_up_bits(xl_h_s);
    const kairn::emulated::Number xl_h = xl_h_n ? xl_h_q : xl_h_s;
    const bool xl_ne = rx == rx;
    const kairn::emulated::Number xl_mi = -std::numeric_limits<kairn::emulated::Number>::infinity();
    const kairn::emulated::Number xl = xl_ne ? xl_l : std::numeric_limits<kairn::emulated::Number>::infinity();
    const kairn::emulated::Number xu = xl_ne ? xl_h : xl_mi;
