    const kairn::emulated::Number yl_l_s_ab = abs_bits(yl_l_nb);
    const bool yl_l_s_m = yl_l_s_ab > yl_l_s_aa;
    const kairn::emulated::Number yl_l_s_h = yl_l_s_m ? yl_l_nb : cy;
    const kairn::emulated::Number yl_l_s_l = yl_l_s_m ? cy : yl_l_nb;
    // (yl_l_s, yl_l_e) = fast_two_sum(yl_l_s_h, yl_l_s_l)
