    const kairn::emulated::Number yl_l_s_z = yl_l_s - yl_l_s_h;
    const kairn::emulated::Number yl_l_e = yl_l_s_l - yl_l_s_z;
    const bool yl_l_n = kairn::emulated::constant(0) > yl_l_e;
    const kairn::emulated::Number yl_l_p = next_down_bits(yl_l_s);
    const kairn::emulated::Number yl_l = yl_l_n ? yl_l_p : yl_l_s;
