    const kairn::emulated::Number yl_h_s_ab = abs_bits(ry);
    const bool yl_h_s_m = yl_h_s_ab > yl_h_s_aa;
    const kairn::emulated::Number yl_h_s_h = yl_h_s_m ? ry : cy;
    const kairn::emulated::Number yl_h_s_l = yl_h_s_m ? cy : ry;
    // (yl_h_s, yl_h_e) = fast_two_sum(yl_h_s_h, yl_h_s_l)
    const kairn::emulated::Number yl_h_s = yl_h_s_h + yl_h_s_l;
    const kairn::emulated::Number yl_h_s_z = yl_h_s - yl_h_s_h;
    const kairn::emulated::Number yl_h_e = yl_h_s_l - yl_h_s_z;
    const bool yl_h_n = yl_h_e > kairn::emulated::constant(0);
    const kairn::emulated::Number yl_h_q = next_up_bits(yl_h_s);
    const kairn::emulated::Number yl_h = yl_h_n ? yl_h_q : yl_h_s;
    const bool yl_ne = ry == ry;
    const kairn::emulated::Number yl_mi = -std::numeric_limits<kairn::emulated::Number>::infinity();
