    const kairn::emulated::Number c_m_mb = c_m_ca ? c_m_l : c_m_ma;
    const bool c_m_cb = c_m_mb > c_m_h;
    const kairn::emulated::Number c_m_mc = c_m_cb ? c_m_h : c_m_mb;
