    // (c_m_ra_s, c_m_ra_e) = two_sum_ord(c_m_mc, c_m_ra_nb)
    const kairn::emulated::Number c_m_ra_s_aa = abs_bits(c_m_mc);
    const kairn::emulated::Number c_m_ra_s_ab = abs_bits(c_m_ra_nb);
    const bool c_m_ra_s_m = c_m_ra_s_ab > c_m_ra_s_aa;
    const kairn::emulated::Number c_m_ra_s_h = c_m_ra_s_m ? c_m_ra_nb : c_m_mc;
    const kairn::emulated::Number c_m_ra_s_l = c_m_ra_s_m ? c_m_mc : c_m_ra_nb;
    // (c_m_ra_s, c_m_ra_e) = fast_two_sum(c_m_ra_s_h, c_m_ra_s_l)
    const kairn::emulated::Number c_m_ra_s = c_m_ra_s_h + c_m_ra_s_l;
    const kairn::emulated::Number c_m_ra_s_z = c_m_ra_s - c_m_ra_s_h;
    const kairn::emulated::Number c_m_ra_e = c_m_ra_s_l - c_m_ra_s_z;
    const bool c_m_ra_n = c_m_ra_e > kairn::emulated::constant(0);
    const kairn::emulated::Number c_m_ra_q = next_up_bits(c_m_ra_s);
    const kairn::emulated::Number c_m_ra = c_m_ra_n ? c_m_ra_q : c_m_ra_s;
    // (c_m_rb) = sub_up_1(c_m_h, c_m_mc)
    const kairn::emulated::Number c_m_rb_nb = -c_m_mc;
    // (c_m_rb) = add_up_1(c_m_h, c_m_rb_nb)
    // (c_m_rb_s, c_m_rb_e) = two_sum_ord(c_m_h, c_m_rb_nb)
    const kairn::emulated::Number c_m_rb_s_aa = abs_bits(c_m_h);
    const kairn::emulated::Number c_m_rb_s_ab = abs_bits(c_m_rb_nb);
    const bool c_m_rb_s_m = c_m_rb_s_ab > c_m_rb_s_aa;
    const kairn::emulated::Number c_m_rb_s_h = c_m_rb_s_m ? c_m_rb_nb : c_m_h;
    const kairn::emulated::Number c_m_rb_s_l = c_m_rb_s_m ? c_m_h : c_m_rb_nb;
    // (c_m_rb_s, c_m_rb_e) = fast_two_sum(c_m_rb_s_h, c_m_rb_s_l)
    const kairn::emulated::Number c_m_rb_s = c_m_rb_s_h + c_m_rb_s_l;
    const kairn::emulated::Number c_m_rb_s_z = c_m_rb_s - c_m_rb_s_h;
    const kairn::emulated::Number c_m_rb_e = c_m_rb_s_l - c_m_rb_s_z;
    const bool c_m_rb_n = c_m_rb_e > kairn::emulated::constant(0);
    const kairn::emulated::Number c_m_rb_q = next_up_bits(c_m_rb_s);
    const kairn::emulated::Number c_m_rb = c_m_rb_n ? c_m_rb_q : c_m_rb_s;
    const bool c_m_rm = c_m_rb > c_m_ra;
    const kairn::emulated::Number c_m_rc = c_m_rm ? c_m_rb : c_m_ra;
    const kairn::emulated::Number c_m_md = c_m_ml ? c_m_mo : c_m_mc;
    const kairn::emulated::Number c_m_me = c_m_mu ? c_m_om : c_m_md;
