    const kairn::emulated::Number d0 = d0_h + d0_l;
    const kairn::emulated::Number d0_z = d0 - d0_h;
    const kairn::emulated::Number d1 = d0_l - d0_z;
    const kairn::emulated::Number ncy = -cy;
    // (g0, g1) = two_sum_ord(cx, ncy)
    const kairn::emulated::Number g0_aa = abs_bits(cx);
    const kairn::emulated::Number g0_ab = abs_bits(ncy);
    const bool g0_m = g0_ab > g0_aa;
    const kairn::emulated::Number g0_h = g0_m ? ncy : cx;
    const kairn::emulated::Number g0_l = g0_m ? cx : ncy;
    // (g0, g1) = fast_two_sum(g0_h, g0_l)
    const kairn::emulated::Number g0 = g0_h + g0_l;
    const kairn::emulated::Number g0_z = g0 - g0_h;
    const kairn::emulated::Number g1 = g0_l - g0_z;
    // (yes) = lt_2_2(s0, s1, d0, d1)
    const bool yes_h = d0 > s0;
    const bool yes_e = s0 == d0;
    const bool yes_l = d1 > s1;
