    const kairn::emulated::Number cz0_sh_t0 = cz0_sh - cz0_sh_bb;
    const kairn::emulated::Number cz0_sh_t1 = cx0 - cz0_sh_t0;
    const kairn::emulated::Number cz0_sh_t2 = cy0 - cz0_sh_bb;
    const kairn::emulated::Number cz0_sl = cz0_sh_t1 + cz0_sh_t2;
