    const kairn::emulated::Number cz0_th_t0 = cz0_th - cz0_th_bb;
    const kairn::emulated::Number cz0_th_t1 = cx1 - cz0_th_t0;
    const kairn::emulated::Number cz0_th_t2 = cy1 - cz0_th_bb;
    const kairn::emulated::Number cz0_tl = cz0_th_t1 + cz0_th_t2;
    const kairn::emulated::Number cz0_c = cz0_sl + cz0_th;
    // (cz0_vh, cz0_vl) = fast_two_sum(cz0_sh, cz0_c)
    const kairn::emulated::Number cz0_vh = cz0_sh + cz0_c;
    const kairn::emulated::Number cz0_vh_z = cz0_vh - cz0_sh;
    const kairn::emulated::Number cz0_vl = cz0_c - cz0_vh_z;
    const kairn::emulated::Number cz0_w = cz0_tl + cz0_vl;
