    const kairn::emulated::Number cz0 = cz0_vh + cz0_w;
    const kairn::emulated::Number cz0_z = cz0 - cz0_vh;
    const kairn::emulated::Number cz1 = cz0_w - cz0_z;
    const kairn::emulated::Number cz0_az = abs_bits(cz0);
    const kairn::emulated::Number cz0_s = rx + ry;
    const kairn::emulated::Number cz0_t = fma_rn(cz0_az, kairn::emulated::constant(33), cz0_s);
    const kairn::emulated::Number rz = fma_rn(cz0_t, kairn::emulated::constant(18), kairn::emulated::constant(2));
    const kairn::emulated::Number q = rx + ry;
    const bool e = q == q;
