    const kairn::emulated::Number l0 = l0_h + l0_l;
    const kairn::emulated::Number l0_z = l0 - l0_h;
    const kairn::emulated::Number l1 = l0_l - l0_z;
    // (h0, h1) = add_up_2_2(c0, c1, p0, p1)
    // (h0_z0, h0_z1, h0_d) = add_ball_2_2(c0, c1, p0, p1)
    // (h0_z0, h0_z1) = add_2_2(c0, c1, p0, p1)
    // (h0_z0_sh, h0_z0_sl) = two_sum(c0, p0)
    const kairn::emulated::Number h0_z0_sh = c0 + p0;
    const kairn::emulated::Number h0_z0_sh_bb = h0_z0_sh - c0;
    const kairn::emulated::Number h0_z0_sh_t0 = h0_z0_sh - h0_z0_sh_bb;
    const kairn::emulated::Number h0_z0_sh_t1 = c0 - h0_z0_sh_t0;
    const kairn::emulated::Number h0_z0_sh_t2 = p0 - h0_z0_sh_bb;
    const kairn::emulated::Number h0_z0_sl = h0_z0_sh_t1 + h0_z0_sh_t2;
    // (h0_z0_th, h0_z0_tl) = two_sum(c1, p1)
    const kairn::emulated::Number h0_z0_th = c1 + p1;
    const kairn::emulated::Number h0_z0_th_bb = h0_z0_th - c1;
    const kairn::emulated::Number h0_z0_th_t0 = h0_z0_th - h0_z0_th_bb;
    const kairn::emulated::Number h0_z0_th_t1 = c1 - h0_z0_th_t0;
    const kairn::emulated::Number h0_z0_th_t2 = p1 - h0_z0_th_bb;
