    const kairn::emulated::Number h0_z0_vh_z = h0_z0_vh - h0_z0_sh;
    const kairn::emulated::Number h0_z0_vl = h0_z0_c - h0_z0_vh_z;
    const kairn::emulated::Number h0_z0_w = h0_z0_tl + h0_z0_vl;
