    const kairn::emulated::Number h0_z1 = h0_z0_w - h0_z0_z;
    const kairn::emulated::Number h0_z0_az = abs_bits(h0_z0);
    const kairn::emulated::Number h0_z0_t = fma_rn(h0_z0_az, kairn::emulated::constant(33), kairn::emulated::constant(0));
