    const kairn::emulated::Number yl0_h0_z0_sh_t2 = yl0_p0 - yl0_h0_z0_sh_bb;
    const kairn::emulated::Number yl0_h0_z0_sl = yl0_h0_z0_sh_t1 + yl0_h0_z0_sh_t2;
    // (yl0_h0_z0_th, yl0_h0_z0_tl) = two_sum(cy1, yl0_p1)
    const kairn::emulated::Number yl0_h0_z0_th = cy1 + yl0_p1;
    const kairn::emulated::Number yl0_h0_z0_th_bb = yl0_h0_z0_th - cy1;
