    const kairn::emulated::Number yl0_h0_z0_th_t1 = cy1 - yl0_h0_z0_th_t0;
    const kairn::emulated::Number yl0_h0_z0_th_t2 = yl0_p1 - yl0_h0_z0_th_bb;
    const kairn::emulated::Number yl0_h0_z0_tl = yl0_h0_z0_th_t1 + yl0_h0_z0_th_t2;
    const kairn::emulated::Number yl0_h0_z0_c = yl0_h0_z0_sl + yl0_h0_z0_th;
    // (yl0_h0_z0_vh, yl0_h0_z0_vl) = fast_two_sum(yl0_h0_z0_sh, yl0_h0_z0_c)
    const kairn::emulated::Number yl0_h0_z0_vh = yl0_h0_z0_sh + yl0_h0_z0_c;
