    const kairn::emulated::Number yl0_h0_z0_az = abs_bits(yl0_h0_z0);
    const kairn::emulated::Number yl0_h0_z0_t = fma_rn(yl0_h0_z0_az, kairn::emulated::constant(33), kairn::emulated::constant(0));
    const kairn::emulated::Number yl0_h0_d = fma_rn(yl0_h0_z0_t, kairn::emulated::constant(18), kairn::emulated::constant(2));
