    // (yl0_h0_w) = add_up_1(yl0_h0_z1, yl0_h0_dd)
    // (yl0_h0_w_s, yl0_h0_w_e) = two_sum_ord(yl0_h0_z1, yl0_h0_dd)
    const kairn::emulated::Number yl0_h0_w_s_aa = abs_bits(yl0_h0_z1);
    const kairn::emulated::Number yl0_h0_w_s_ab = abs_bits(yl0_h0_dd);
