    const kairn::emulated::Number yl0_h0_ab = abs_bits(yl0_h0_w);
    const bool yl0_h0_m = yl0_h0_ab > yl0_h0_aa;
    const kairn::emulated::Number yl0_h0_h = yl0_h0_m ? yl0_h0_w : yl0_h0_z0;
    const kairn::emulated::Number yl0_h0_l = yl0_h0_m ? yl0_h0_z0 : yl0_h0_w;
    // (yl0_h0, yl0_h1) = fast_two_sum(yl0_h0_h, yl0_h0_l)
    const kairn::emulated::Number yl0_h0 = yl0_h0_h + yl0_h0_l;
    const kairn::emulated::Number yl0_h0_z = yl0_h0 - yl0_h0_h;
    const kairn::emulated::Number yl0_h1 = yl0_h0_l - yl0_h0_z;
    const kairn::emulated::Number yl0_al = abs_bits(yl0_l0);
    const bool yl0_fl = std::numeric_limits<kairn::emulated::Number>::infinity() > yl0_al;
    const kairn::emulated::Number yl0_ah = abs_bits(yl0_h0);
    const bool yl0_fh = std::numeric_limits<kairn::emulated::Number>::infinity() > yl0_ah;
    const kairn::emulated::Number yl0_mi = -std::numeric_limits<kairn::emulated::Number>::infinity();
    const kairn::emulated::Number yl0_a0 = yl0_fl ? yl0_l0 : yl0_mi;
    const kairn::emulated::Number yl0_a1 = yl0_fl ? yl0_l1 : kairn::emulated::constant(0);
    const kairn::emulated::Number yl0_b0 = yl0_fh ? yl0_h0 : std::numeric_limits<kairn::emulated::Number>::infinity();
    const kairn::emulated::Number yl0_b1 = yl0_fh ? yl0_h1 : kairn::emulated::constant(0);
    const bool yl0_ne = ry == ry;
    const kairn::emulated::Number yl0 = yl0_ne ? yl0_a0 : std::numeric_limits<kairn::emulated::Number>::infinity();
    const kairn::emulated::Number yl1 = yl0_ne ? yl0_a1 : kairn::emulated::constant(0);
    const kairn::emulated::Number yu0 = yl0_ne ? yl0_b0 : yl0_mi;
    const kairn::emulated::Number yu1 = yl0_ne ? yl0_b1 : kairn::emulated::constant(0);
    // (zl0, zl1, zu0, zu1) = interval_intersection_2(xl0, xl1, xu0, xu1, yl0, yl1, yu0, yu1)
    // (zl0_ml) = lt_2_2(xl0, xl1, yl0, yl1)
    const bool zl0_ml_h = yl0 > xl0;
    const bool zl0_ml_e = xl0 == yl0;
    const bool zl0_ml_l = yl1 > xl1;
    const bool zl0_ml_t = zl0_ml_e & zl0_ml_l;
    const bool zl0_ml = zl0_ml_h | zl0_ml_t;
    const kairn::emulated::Number zl0_l0 = zl0_ml ? yl0 : xl0;
    const kairn::emulated::Number zl0_l1 = zl0_ml ? yl1 : xl1;
    // (zl0_mu) = lt_2_2(yu0, yu1, xu0, xu1)
    const bool zl0_mu_h = xu0 > yu0;
    const bool zl0_mu_e = yu0 == xu0;
    const bool zl0_mu_l = xu1 > yu1;
    const bool zl0_mu_t = zl0_mu_e & zl0_mu_l;
    const bool zl0_mu = zl0_mu_h | zl0_mu_t;
    const kairn::emulated::Number zl0_h0 = zl0_mu ? yu0 : xu0;
    const kairn::emulated::Number zl0_h1 = zl0_mu ? yu1 : xu1;
    // (zl0_ok) = le_2_2(zl0_l0, zl0_l1, zl0_h0, zl0_h1)
    const bool zl0_ok_h = zl0_h0 > zl0_l0;
    const bool zl0_ok_e = zl0_l0 == zl0_h0;
    const bool zl0_ok_l = zl0_h1 >= zl0_l1;
    const bool zl0_ok_t = zl0_ok_e & zl0_ok_l;
    const bool zl0_ok = zl0_ok_h | zl0_ok_t;
    const kairn::emulated::Number zl0_mi = -std::numeric_limits<kairn::emulated::Number>::infinity();
    const kairn::emulated::Number zl0 = zl0_ok ? zl0_l0 : std::numeric_limits<kairn::emulated::Number>::infinity();
    const kairn::emulated::Number zl1 = zl0_ok ? zl0_l1 : kairn::emulated::constant(0);
    const kairn::emulated::Number zu0 = zl0_ok ? zl0_h0 : zl0_mi;
    const kairn::emulated::Number zu1 = zl0_ok ? zl0_h1 : kairn::emulated::constant(0);
    // (c0, c1, r) = interval_to_ball_2(zl0, zl1, zu0, zu1)
    // (c0_m0, c0_m1, r) = interval_mid_rad_2(zl0, zl1, zu0, zu1)
    const kairn::emulated::Number c0_m0_om = next_down_bits(std::numeric_limits<kairn::emulated::Number>::infinity());
    const kairn::emulated::Number c0_m0_mo = -c0_m0_om;
    const bool c0_m0_ml = c0_m0_mo > zl0;
    const kairn::emulated::Number c0_m0_l0 = c0_m0_ml ? c0_m0_mo : zl0;
    const kairn::emulated::Number c0_m0_l1 = c0_m0_ml ? kairn::emulated::constant(0) : zl1;
    const bool c0_m0_mu = zu0 > c0_m0_om;
    const kairn::emulated::Number c0_m0_h0 = c0_m0_mu ? c0_m0_om : zu0;
    const kairn::emulated::Number c0_m0_h1 = c0_m0_mu ? kairn::emulated::constant(0) : zu1;
    // (c0_m0_hl0, c0_m0_hl1) = mul_pow2_2(c0_m0_l0, c0_m0_l1, const up(1/2))
    const kairn::emulated::Number c0_m0_hl0_h = fma_rn(c0_m0_l0, kairn::emulated::constant(26), kairn::emulated::constant(0));
    const kairn::emulated::Number c0_m0_hl0_l = fma_rn(c0_m0_l1, kairn::emulated::constant(26), kairn::emulated::constant(0));
    // (c0_m0_hl0, c0_m0_hl1) = fast_two_sum(c0_m0_hl0_h, c0_m0_hl0_l)
    const kairn::emulated::Number c0_m0_hl0 = c0_m0_hl0_h + c0_m0_hl0_l;
    const kairn::emulated::Number c0_m0_hl0_z = c0_m0_hl0 - c0_m0_hl0_h;
    const kairn::emulated::Number c0_m0_hl1 = c0_m0_hl0_l - c0_m0_hl0_z;
    // (c0_m0_hu0, c0_m0_hu1) = mul_pow2_2(c0_m0_h0, c0_m0_h1, const up(1/2))
    const kairn::emulated::Number c0_m0_hu0_h = fma_rn(c0_m0_h0, kairn::emulated::constant(26), kairn::emulated::constant(0));
    const kairn::emulated::Number c0_m0_hu0_l = fma_rn(c0_m0_h1, kairn::emulated::constant(26), kairn::emulated::constant(0));
    // (c0_m0_hu0, c0_m0_hu1) = fast_two_sum(c0_m0_hu0_h, c0_m0_hu0_l)
    const kairn::emulated::Number c0_m0_hu0 = c0_m0_hu0_h + c0_m0_hu0_l;
    const kairn::emulated::Number c0_m0_hu0_z = c0_m0_hu0 - c0_m0_hu0_h;
    const kairn::emulated::Number c0_m0_hu1 = c0_m0_hu0_l - c0_m0_hu0_z;
    // (c0_m0_ma0, c0_m0_ma1) = add_2_2(c0_m0_hl0, c0_m0_hl1, c0_m0_hu0, c0_m0_hu1)
    // (c0_m0_ma0_sh, c0_m0_ma0_sl) = two_sum(c0_m0_hl0, c0_m0_hu0)
    const kairn::emulated::Number c0_m0_ma0_sh = c0_m0_hl0 + c0_m0_hu0;
    const kairn::emulated::Number c0_m0_ma0_sh_bb = c0_m0_ma0_sh - c0_m0_hl0;
    const kairn::emulated::Number c0_m0_ma0_sh_t0 = c0_m0_ma0_sh - c0_m0_ma0_sh_bb;
    const kairn::emulated::Number c0_m0_ma0_sh_t1 = c0_m0_hl0 - c0_m0_ma0_sh_t0;
    const kairn::emulated::Number c0_m0_ma0_sh_t2 = c0_m0_hu0 - c0_m0_ma0_sh_bb;
    const kairn::emulated::Number c0_m0_ma0_sl = c0_m0_ma0_sh_t1 + c0_m0_ma0_sh_t2;
    // (c0_m0_ma0_th, c0_m0_ma0_tl) = two_sum(c0_m0_hl1, c0_m0_hu1)
    const kairn::emulated::Number c0_m0_ma0_th = c0_m0_hl1 + c0_m0_hu1;
    const kairn::emulated::Number c0_m0_ma0_th_bb = c0_m0_ma0_th - c0_m0_hl1;
    const kairn::emulated::Number c0_m0_ma0_th_t0 = c0_m0_ma0_th - c0_m0_ma0_th_bb;
    const kairn::emulated::Number c0_m0_ma0_th_t1 = c0_m0_hl1 - c0_m0_ma0_th_t0;
    const kairn::emulated::Number c0_m0_ma0_th_t2 = c0_m0_hu1 - c0_m0_ma0_th_bb;
    const kairn::emulated::Number c0_m0_ma0_tl = c0_m0_ma0_th_t1 + c0_m0_ma0_th_t2;
    const kairn::emulated::Number c0_m0_ma0_c = c0_m0_ma0_sl + c0_m0_ma0_th;
    // (c0_m0_ma0_vh, c0_m0_ma0_vl) = fast_two_sum(c0_m0_ma0_sh, c0_m0_ma0_c)
    const kairn::emulated::Number c0_m0_ma0_vh = c0_m0_ma0_sh + c0_m0_ma0_c;
    const kairn::emulated::Number c0_m0_ma0_vh_z = c0_m0_ma0_vh - c0_m0_ma0_sh;
    const kairn::emulated::Number c0_m0_ma0_vl = c0_m0_ma0_c - c0_m0_ma0_vh_z;
    const kairn::emulated::Number c0_m0_ma0_w = c0_m0_ma0_tl + c0_m0_ma0_vl;
    // (c0_m0_ma0, c0_m0_ma1) = fast_two_sum(c0_m0_ma0_vh, c0_m0_ma0_w)
    const kairn::emulated::Number c0_m0_ma0 = c0_m0_ma0_vh + c0_m0_ma0_w;
    const kairn::emulated::Number c0_m0_ma0_z = c0_m0_ma0 - c0_m0_ma0_vh;
    const kairn::emulated::Number c0_m0_ma1 = c0_m0_ma0_w - c0_m0_ma0_z;
    // (c0_m0_ca) = lt_2_2(c0_m0_ma0, c0_m0_ma1, c0_m0_l0, c0_m0_l1)
    const bool c0_m0_ca_h = c0_m0_l0 > c0_m0_ma0;
    const bool c0_m0_ca_e = c0_m0_ma0 == c0_m0_l0;
