    const kairn::emulated::Number c0_m0_mb1 = c0_m0_ca ? c0_m0_l1 : c0_m0_ma1;
    // (c0_m0_cb) = lt_2_2(c0_m0_h0, c0_m0_h1, c0_m0_mb0, c0_m0_mb1)
    const bool c0_m0_cb_h = c0_m0_mb0 > c0_m0_h0;
