    const bool c0_m0_cb = c0_m0_cb_h | c0_m0_cb_t;
    const kairn::emulated::Number c0_m0_mc0 = c0_m0_cb ? c0_m0_h0 : c0_m0_mb0;
    const kairn::emulated::Number c0_m0_mc1 = c0_m0_cb ? c0_m0_h1 : c0_m0_mb1;
    const kairn::emulated::Number c0_m0_nl0 = -c0_m0_l0;
    const kairn::emulated::Number c0_m0_nl1 = -c0_m0_l1;
    // (c0_m0_za0, c0_m0_za1, c0_m0_ea) = add_ball_2_2(c0_m0_mc0, c0_m0_mc1, c0_m0_nl0, c0_m0_nl1)
    // (c0_m0_za0, c0_m0_za1) = add_2_2(c0_m0_mc0, c0_m0_mc1, c0_m0_nl0, c0_m0_nl1)
    // (c0_m0_za0_sh, c0_m0_za0_sl) = two_sum(c0_m0_mc0, c0_m0_nl0)
    const kairn::emulated::Number c0_m0_za0_sh = c0_m0_mc0 + c0_m0_nl0;
    const kairn::emulated::Number c0_m0_za0_sh_bb = c0_m0_za0_sh - c0_m0_mc0;
    const kairn::emulated::Number c0_m0_za0_sh_t0 = c0_m0_za0_sh - c0_m0_za0_sh_bb;
    const kairn::emulated::Number c0_m0_za0_sh_t1 = c0_m0_mc0 - c0_m0_za0_sh_t0;
    const kairn::emulated::Number c0_m0_za0_sh_t2 = c0_m0_nl0 - c0_m0_za0_sh_bb;
