    const kairn::emulated::Number c0_m0_za0_th = c0_m0_mc1 + c0_m0_nl1;
    const kairn::emulated::Number c0_m0_za0_th_bb = c0_m0_za0_th - c0_m0_mc1;
    const kairn::emulated::Number c0_m0_za0_th_t0 = c0_m0_za0_th - c0_m0_za0_th_bb;
