    // (c0_m0_za0_vh, c0_m0_za0_vl) = fast_two_sum(c0_m0_za0_sh, c0_m0_za0_c)
    const kairn::emulated::Number c0_m0_za0_vh = c0_m0_za0_sh + c0_m0_za0_c;
    const kairn::emulated::Number c0_m0_za0_vh_z = c0_m0_za0_vh - c0_m0_za0_sh;
