    const kairn::emulated::Number c0_m0_zb0_az = abs_bits(c0_m0_zb0);
    const kairn::emulated::Number c0_m0_zb0_t = fma_rn(c0_m0_zb0_az, kairn::emulated::constant(33), kairn::emulated::constant(0));
    const kairn::emulated::Number c0_m0_eb = fma_rn(c0_m0_zb0_t, kairn::emulated::constant(18), kairn::emulated::constant(2));
    // (c0_m0_tb) = to_up_2(c0_m0_zb0, c0_m0_zb1)
