    const kairn::emulated::Number z0_sh_bb = z0_sh - cy0;
    const kairn::emulated::Number z0_sh_t0 = z0_sh - z0_sh_bb;
    const kairn::emulated::Number z0_sh_t1 = cy0 - z0_sh_t0;
    const kairn::emulated::Number z0_sh_t2 = ncx0 - z0_sh_bb;
    const kairn::emulated::Number z0_sl = z0_sh_t1 + z0_sh_t2;
