    const kairn::emulated::Number l0_z0_th_bb = l0_z0_th - xl1;
    const kairn::emulated::Number l0_z0_th_t0 = l0_z0_th - l0_z0_th_bb;
    const kairn::emulated::Number l0_z0_th_t1 = xl1 - l0_z0_th_t0;
    const kairn::emulated::Number l0_z0_th_t2 = yl1 - l0_z0_th_bb;
