    const kairn::emulated::Number l0_z0_w = l0_z0_tl + l0_z0_vl;
    // (l0_z0, l0_z1) = fast_two_sum(l0_z0_vh, l0_z0_w)
    const kairn::emulated::Number l0_z0 = l0_z0_vh + l0_z0_w;
