    const kairn::emulated::Number c0_p1 = c0_fc ? c0_c1 : kairn::emulated::constant(0);
    const kairn::emulated::Number c0_q0 = c0_fe ? c0_e0 : std::numeric_limits<kairn::emulated::Number>::infinity();
    const kairn::emulated::Number c0_q1 = c0_fe ? c0_e1 : kairn::emulated::constant(0);
    const kairn::emulated::Number c0_r0 = c0_fo ? c0_p0 : c0_t;
    const kairn::emulated::Number c0_r1 = c0_fo ? c0_p1 : kairn::emulated::constant(0);
    const kairn::emulated::Number c0_s0 = c0_fo ? c0_q0 : c0_t;
    const kairn::emulated::Number c0_s1 = c0_fo ? c0_q1 : kairn::emulated::constant(0);
    const kairn::emulated::Number c0 = c0_nz ? c0_r0 : kairn::emulated::constant(0);
    const kairn::emulated::Number c1 = c0_nz ? c0_r1 : kairn::emulated::constant(0);
    const kairn::emulated::Number g0 = c0_nz ? c0_s0 : kairn::emulated::constant(0);
    const kairn::emulated::Number g1 = c0_nz ? c0_s1 : kairn::emulated::constant(0);
    // (d0, d1, h0, h1) = mul_ext_2_2(xu0, xu1, yu0, yu1)
    // (d0_c0, d0_c1, d0_e0, d0_e1) = mul_dir_2_2(xu0, xu1, yu0, yu1)
    // (d0_c0_z0, d0_c0_z1, d0_c0_d) = mul_ball_2_2(xu0, xu1, yu0, yu1)
    // (d0_c0_z0, d0_c0_z1) = mul_2_2(xu0, xu1, yu0, yu1)
    // (d0_c0_z0_ch, d0_c0_z0_cl1) = two_prod(xu0, yu0)
    const kairn::emulated::Number d0_c0_z0_ch = fma_rn(xu0, yu0, kairn::emulated::constant(0));
    const kairn::emulated::Number d0_c0_z0_cl1 = fma_rn(xu0, yu0, -d0_c0_z0_ch);
    const kairn::emulated::Number d0_c0_z0_tl0 = fma_rn(xu1, yu1, kairn::emulated::constant(0));
    const kairn::emulated::Number d0_c0_z0_tl1 = fma_rn(xu0, yu1, d0_c0_z0_tl0);
    const kairn::emulated::Number d0_c0_z0_cl2 = fma_rn(xu1, yu0, d0_c0_z0_tl1);
    const kairn::emulated::Number d0_c0_z0_cl3 = d0_c0_z0_cl1 + d0_c0_z0_cl2;
    // (d0_c0_z0, d0_c0_z1) = fast_two_sum(d0_c0_z0_ch, d0_c0_z0_cl3)
    const kairn::emulated::Number d0_c0_z0 = d0_c0_z0_ch + d0_c0_z0_cl3;
    const kairn::emulated::Number d0_c0_z0_z = d0_c0_z0 - d0_c0_z0_ch;
    const kairn::emulated::Number d0_c0_z1 = d0_c0_z0_cl3 - d0_c0_z0_z;
    const kairn::emulated::Number d0_c0_z0_az = abs_bits(d0_c0_z0);
    const kairn::emulated::Number d0_c0_z0_t = fma_rn(d0_c0_z0_az, kairn::emulated::constant(36), kairn::emulated::constant(0));
    const kairn::emulated::Number d0_c0_d = fma_rn(d0_c0_z0_t, kairn::emulated::constant(20), kairn::emulated::constant(6));
    const kairn::emulated::Number d0_c0_nz = -d0_c0_z1;
    // (d0_c0_t) = add_up_1(d0_c0_d, d0_c0_nz)
    // (d0_c0_t_s, d0_c0_t_e) = two_sum_ord(d0_c0_d, d0_c0_nz)
    const kairn::emulated::Number d0_c0_t_s_aa = abs_bits(d0_c0_d);
    const kairn::emulated::Number d0_c0_t_s_ab = abs_bits(d0_c0_nz);
