        const kairn::emulated::Number step_z0_sh_bb = step_z0_sh - x0;
        const kairn::emulated::Number step_z0_sh_t0 = step_z0_sh - step_z0_sh_bb;
        const kairn::emulated::Number step_z0_sh_t1 = x0 - step_z0_sh_t0;
        const kairn::emulated::Number step_z0_sh_t2 = step_n0 - step_z0_sh_bb;
        const kairn::emulated::Number step_z0_sl = step_z0_sh_t1 + step_z0_sh_t2;
        // (step_z0_th, step_z0_tl) = two_sum(x1, step_n1)
        const kairn::emulated::Number step_z0_th = x1 + step_n1;
        const kairn::emulated::Number step_z0_th_bb = step_z0_th - x1;
        const kairn::emulated::Number step_z0_th_t0 = step_z0_th - step_z0_th_bb;
        const kairn::emulated::Number step_z0_th_t1 = x1 - step_z0_th_t0;
        const kairn::emulated::Number step_z0_th_t2 = step_n1 - step_z0_th_bb;
        const kairn::emulated::Number step_z0_tl = step_z0_th_t1 + step_z0_th_t2;
        const kairn::emulated::Number step_z0_c = step_z0_sl + step_z0_th;
        // (step_z0_vh, step_z0_vl) = fast_two_sum(step_z0_sh, step_z0_c)
        const kairn::emulated::Number step_z0_vh = step_z0_sh + step_z0_c;
        const kairn::emulated::Number step_z0_vh_z = step_z0_vh - step_z0_sh;
        const kairn::emulated::Number step_z0_vl = step_z0_c - step_z0_vh_z;
        const kairn::emulated::Number step_z0_w = step_z0_tl + step_z0_vl;
        // (step_z0, step_z1) = fast_two_sum(step_z0_vh, step_z0_w)
        const kairn::emulated::Number step_z0 = step_z0_vh + step_z0_w;
        const kairn::emulated::Number step_z0_z = step_z0 - step_z0_vh;
        const kairn::emulated::Number step_z1 = step_z0_w - step_z0_z;
        z0_out[i_] = step_z0;
        z1_out[i_] = step_z1;
